insert into pg_temp.vibeschool_ca11_unit02_packet(data)
values ($unit02data${"manifest":{"id":"vibeschool-originals-cpa-ca11-unit02-accounting-process-v1","title":"From Evidence to Financial Statements","qualification":"KASNEB CPA","paper":"CA11 Financial Accounting","level":"Foundation","unit":"02","source_version":"2024-06","syllabus_section":"2. The Accounting Process and Systems","coverage":["2.1","2.2","2.3","2.4","2.5"],"release_state":"in_review","review_method":"Original educational authorship; source-scope mapping, technical ledger recalculation, question/answer-key integrity tests, editorial challenge and fail-closed publication checks. Independent human-professional sign-off not claimed.","sources":[{"authority":"KASNEB","url":"https://www.kasneb.or.ke/wp-content/uploads/2024/09/CPA-Syllabus-Reviewed-June-2024.pdf","locator":"Foundation Paper No. 1, printed page 1, syllabus section 2.1–2.5","purpose":"primary course outcome and examinable scope"},{"authority":"KASNEB","url":"https://www.kasneb.or.ke/sites/default/files/2026-04/QUALIFICATIONS%20BOOKLET.pdf","locator":"Foundation Level CA11","purpose":"current dated paper identity (2026)"},{"authority":"ACCA","url":"https://www.accaglobal.com/gb/en/student/exam-support-resources/foundation-level-study-resources/fa2/fa2-technical-articles/a-matter-of-principle.html","locator":"Duality section","purpose":"external technical check of debit/credit concepts"},{"authority":"ACCA","url":"https://www.accaglobal.com/africa/en/student/exam-support-resources/foundation-level-study-resources/fa1/technical-articles/sales-comp-acc-system.html","locator":"Sales and purchases in a computerised accounting system","purpose":"modern journal, customer and subsidiary-ledger recording"},{"authority":"IFRS Foundation","url":"https://www.ifrs.org/issued-standards/list-of-standards/conceptual-framework/","locator":"Elements and objective of financial statements","purpose":"financial-reporting conceptual guardrails"}],"learning_goals":["Explain and trace source documentation before journal entry","Distinguish credit sales/purchases journals, returns, cash books, general journal and petty cash imprest","Record and post basic double entries with correct account classifications","Extract and verify debit and credit ledger balances in a trial balance","Prepare and reconcile introductory profit-or-loss and position statements without claiming full-framework compliance"],"originality":"VibeSchool-written original teaching scenarios, exercises, model feedback and examples; syllabus headings are only used as scope references.","assumptions":["August 2026 scenario is fictional; Nuru Repair Studio is a sole-trader service enterprise.","Opening ledger balances are zero.","No VAT, income tax, depreciation, inventories, other adjustments or regulatory statutory filing is calculated.","Advertising services are used entirely in August and are a period expense.","KSh 9,000 quotation enquiry is not recorded as a transaction.","Simple statement example is introductory, not a complete IFRS annual financial statement."],"case_transactions":[{"id":1,"event":"Owner capital paid into bank","debit":"bank","credit":"capital","amount":180000},{"id":2,"event":"Equipment purchased by bank","debit":"equipment","credit":"bank","amount":60000},{"id":3,"event":"Repairs completed on credit","debit":"receivables","credit":"revenue","amount":35000},{"id":4,"event":"Completed repair fees banked","debit":"bank","credit":"revenue","amount":45000},{"id":5,"event":"August rent paid from bank","debit":"rent","credit":"bank","amount":12000},{"id":6,"event":"Advertising delivered on supplier credit","debit":"advertising","credit":"payables","amount":8000},{"id":7,"event":"Earlier customer debt partly collected","debit":"bank","credit":"receivables","amount":20000},{"id":8,"event":"Advertising payable partly settled","debit":"payables","credit":"bank","amount":5000},{"id":9,"event":"Owner drawings paid from bank","debit":"drawings","credit":"bank","amount":4000}],"case_unposted_event":{"date":"2026-08-27","event":"Customer requests quotation for future repairs","quoted_amount":9000,"reason":"No work done and no binding transaction assumed; no recognised event."},"expected_balances":{"bank":164000,"equipment":60000,"receivables":15000,"rent":12000,"advertising":8000,"drawings":4000,"capital":-180000,"revenue":-80000,"payables":-3000},"expected_totals":{"trial_debits":263000,"trial_credits":263000,"monthly_revenue":80000,"monthly_expenses":20000,"monthly_profit":60000,"assets":239000,"liabilities":3000,"equity":236000},"covered_first_unit":["1.1","1.2","1.3","1.4","1.5"],"future_out_of_scope":"Later CA11 sections 3–12, year-end adjustments, accruals, depreciation, cash-flow preparation, company and partnership statements, bank reconciliation and public-sector accounting.","publication_boundary":"Retain existing published CA11 Unit 01 identities, authorisation policies, source evidence, learner progress and other CPA papers; only exact new five-topic set may become published after gate."},"topics":[{"slug":"source-documents-and-evidence","title":"A transaction begins with evidence","subtitle":"Section 2.1 · Invoices, receipts, statements and a defensible audit trail","sequence_number":4,"week_number":null,"concept_tab":[{"title":"Begin at the counter","text":"A customer buys goods on credit for KSh 24,000. The shop issues an invoice; no money changes hands yet. Two weeks later, the customer pays KSh 10,000 by bank transfer. The invoice supports the sale and receivable. The bank credit supports the later collection. If an accountant records the sale as bank cash on the invoice date, the figures stop describing what actually happened."},{"title":"The question behind every document","text":"Before entering any amount, establish five things: who transacted, what was supplied or paid, when the event occurred, what amount is supported, and whether settlement has happened. The reference number helps you connect the document to the journal entry and any subsequent correction. A missing piece is a reason to ask for evidence, not to invent a number."},{"title":"An invoice records a claim or obligation","text":"A sales invoice describes goods or services supplied to a customer and the amount charged. For a credit transaction, it ordinarily supports a receivable for the seller and a payable for the buyer, subject to the proper recognition rules. Issuing an invoice does not prove cash was received. A purchase invoice is the corresponding evidence viewed from the purchaser's side."},{"title":"A receipt records payment","text":"A receipt or verified bank transaction provides evidence of settlement. Suppose a customer pays KSh 6,000 against an earlier KSh 16,000 credit invoice. Record the KSh 6,000 as a reduction of the customer's outstanding balance; the remaining receivable is KSh 10,000. Do not report a second sale when the previously recognised invoice is paid."},{"title":"Returns and credit notes","text":"A customer returns goods that were sold on credit for KSh 3,000. After the return is accepted, a credit note can reduce the original KSh 24,000 amount owed to KSh 21,000. A credit note is not the same as proof that KSh 3,000 was refunded in cash. The accounting effect depends on whether the original sale remains unpaid or had already been settled."},{"title":"Bank, mobile money and supporting records","text":"Bank statements and mobile-money transaction confirmations help verify the amount, date and counterparty of a transfer. They support reconciliation with the cash book. A payment notification on its own may not establish what goods were purchased or whether a supply was for business rather than the owner's private use. Match the payment to an invoice, agreement or other appropriate evidence."},{"title":"Build an evidence trail you can follow back","text":"A good accounting record can be traced both ways: from document to entry and from ledger balance back to the underlying documents. Keep source references, transaction dates, supplier or customer identifiers and explanations. Corrections should leave an intelligible history; silently replacing the original record makes later checking more difficult."},{"title":"Try it as the accountant","text":"An invoice dated 4 July shows KSh 18,000 supplied on credit. A bank statement dated 19 July shows KSh 7,000 received from that customer. You should be able to identify two events, not one. The customer owes KSh 11,000 at 19 July if there are no other invoices, returns or payments. Explain which document supports each event before moving to the next lesson."}],"kenya_context_tab":[{"title":"A repair workshop's file","text":"A Nakuru repair workshop invoices a customer KSh 12,500 for completed repairs. A mobile-money confirmation for KSh 5,000 arrives later. The customer ledger should show the original claim, the part-payment and KSh 7,500 still outstanding. Neither the mobile-money reference nor the invoice should be discarded merely because the other exists."},{"title":"Evidence and electronic accounting","text":"A spreadsheet or accounting app can hold copies of approved source documents and link them to entries. An accountant still checks for duplicates, dates, business purpose and correct allocation. Software speeds up recording; it does not transform an unsupported transaction into reliable evidence."}],"common_errors_tab":[{"title":"Treating an invoice as a receipt","text":"A sales invoice supports a sale or claim, not proof of settlement. The cash or bank record changes only when a genuine cash movement occurs, unless another specific accounting treatment applies."},{"title":"Mixing business and personal transactions","text":"A payment from a business account can still be the owner's drawing. Read the purpose and supporting evidence before deciding to charge an expense to the business."}],"clinical_tip_tab":[{"title":"A professional challenge","text":"For any transaction, try answering this without looking at the account names: What happened, when did it happen, how do I know, and what is still unsettled? If the record cannot answer those questions, it needs attention before posting."}]},{"slug":"books-of-original-entry","title":"Choose the right first record","subtitle":"Section 2.2 · Sales, purchases, cash books, journals and petty cash","sequence_number":5,"week_number":null,"concept_tab":[{"title":"Why the first record matters","text":"Source documents arrive in no particular order: a cash transfer, a supplier invoice, a customer return and a receipt from a debtor may all land on the same desk. Books of original entry organise that evidence before the amounts reach ledger accounts. Whether the system uses paper books or software screens, it must retain the classification and trail."},{"title":"Credit sales of goods","text":"In a traditional manual system, the sales day book (sales journal) records credit sales of goods held for resale. An invoice for KSh 22,000 of goods sold on credit belongs here. Cash sales go through the cash book; sales of equipment or other non-trading assets are normally handled differently, often through a general journal. Do not enter every invoice blindly into the sales day book."},{"title":"Credit purchases of goods","text":"The purchases day book records goods bought on credit for resale in the traditional trading-business model. An invoice for KSh 14,000 of resale inventory belongs here. Credit purchase of equipment is not a trading-goods purchase and normally goes through the general journal. Purchases paid for immediately are entered through the cash book or an integrated cash/expense workflow."},{"title":"Returns and adjustments","text":"Sales returns from customers can be captured in the returns-inwards day book; returns to suppliers in the returns-outwards day book. Link the entry to the credit note and original invoice. In a simple example, returning KSh 2,000 of goods previously bought on credit reduces both the goods purchased and the amount due to the supplier; it does not create cash without a refund."},{"title":"The cash book","text":"The cash book tracks cash and bank receipts and payments. A customer depositing KSh 10,000 against an outstanding invoice belongs in the bank-receipts side. Paying the electricity bill of KSh 4,500 by bank transfer belongs on the payments side. Cash books can themselves form part of the double-entry system; do not post an extra, duplicate cash entry when moving data to ledgers."},{"title":"The general journal","text":"A general journal is used for transactions that do not fit the specialised day books, and for many adjustments. Equipment costing KSh 30,000 bought on supplier credit may be recorded as debit equipment, credit trade payable. Explain the entry, date it and reference the supporting invoice. Journal entries are also used by accounting software even where no physical journal book exists."},{"title":"Petty cash: the imprest in action","text":"A workshop starts a petty-cash float of KSh 5,000. During the week it pays KSh 1,250 for courier charges, KSh 700 for staff refreshments and KSh 850 for stationery. Total vouchers are KSh 2,800; cash remaining is KSh 2,200. Replenishing KSh 2,800 restores the float to KSh 5,000. The spending is recorded as the relevant expenses; topping up the float is not a second expense."},{"title":"From document to posting","text":"Take the KSh 14,000 credit inventory invoice. Step 1: confirm that the goods are for resale, not equipment. Step 2: record it once in the purchases day book. Step 3: credit the supplier's account for KSh 14,000 and post to the appropriate purchases account under the chosen accounting system. Step 4: use the same invoice number to trace the entry and check that the supplier total agrees."},{"title":"One business, one posting","text":"Many modern systems post sales, receivables, inventory and bank entries automatically when an invoice or receipt is accepted. The accountant must still know which accounts the software affects. The discipline is the same as in a manual system: each underlying transaction is recognised once, accurately, with a retrievable source and a clear correction trail."}],"kenya_context_tab":[{"title":"A Kenyan shop's end-of-day review","text":"At the close of business, a small Kisumu stationery shop reviews credit-sales invoices, bank receipts and two supplier credit notes. The operator checks that each source has the correct date and class before closing the day's journals. This avoids recording a customer bank transfer as a fresh sale merely because money arrived."},{"title":"An electronic petty-cash box","text":"A team member sends a courier voucher for KSh 1,250 and a supervisor authorises the claim. The cash keeper records the payment, attaches the voucher and updates the float. On replenishment, the keeper reconciles vouchers plus cash in hand to the authorised KSh 5,000 before requesting funds."}],"common_errors_tab":[{"title":"Credit purchase does not mean any purchase","text":"Only credit purchases of trading goods belong in the traditional purchases day book. A machine bought on credit needs classification as a non-current asset, not an ordinary resale purchase."},{"title":"Recording a reimbursement twice","text":"A replenishment of petty cash replaces what was spent; it should not repeat the expenses already captured by the vouchers. A balanced float with duplicate expense entries is still wrong."},{"title":"Modern systems and old terminology","text":"Computerised books may not literally use separate bound journals. Learn the underlying transaction classification and double-entry effect, rather than treating a menu label as an accounting principle."}],"clinical_tip_tab":[{"title":"Test the document path","text":"For each example, name the source first, then the first book or software workflow, and finally the accounts affected. If you cannot say what the credit sale or payment does to a supplier or customer balance, review the transaction before memorising another label."}]},{"slug":"double-entry-ledgers","title":"Make each transaction balance","subtitle":"Section 2.3 · Journals, T-accounts and the ledger in practice","sequence_number":6,"week_number":null,"concept_tab":[{"title":"Debit and credit are positions, not praise or blame","text":"A debit is the left side of an account; a credit is the right. Neither word means good, bad, cash in or cash out in every case. The same bank account can be debited when money enters and credited when money leaves. The rules depend on which kind of account changed."},{"title":"The five movements to recognise","text":"Assets and expenses normally increase with debits. Liabilities, capital and income normally increase with credits. Drawings increase with debits because they reduce the owner's interest. When any of these accounts decreases, use its opposite side. Keep the accounting equation in mind rather than chanting a mnemonic without understanding the event."},{"title":"Our working case: Nuru Repair Studio","text":"Nuru Repair Studio opens on 1 August with no opening balances. During August it has nine recordable transactions and one customer enquiry that must not be posted. For this introductory case, ignore VAT, depreciation, tax and other year-end adjustments. The advertising services are fully used in August. The same figures will reappear in the trial balance and financial statements, so follow every amount carefully."},{"title":"Transaction 1 and 2: capital and equipment","text":"1 August: the owner pays KSh 180,000 into the business bank. Debit bank KSh 180,000; credit capital KSh 180,000. The business gains cash and the owner gains an equity interest. 3 August: it buys a repair machine for KSh 60,000 by bank transfer. Debit equipment KSh 60,000; credit bank KSh 60,000. One asset replaces part of another; no operating expense is recognised in this simple purchase entry."},{"title":"Transactions 3 to 5: earning and paying","text":"5 August: repairs are completed for a customer on credit, KSh 35,000. Debit trade receivables KSh 35,000; credit service revenue KSh 35,000. 7 August: cash repair fees of KSh 45,000 are banked. Debit bank KSh 45,000; credit service revenue KSh 45,000. 10 August: August rent of KSh 12,000 is paid from the bank. Debit rent expense KSh 12,000; credit bank KSh 12,000."},{"title":"Transactions 6 to 8: credit and collection","text":"12 August: advertising worth KSh 8,000 is fully delivered and invoiced, payment due later. Debit advertising expense KSh 8,000; credit trade payables KSh 8,000. 18 August: KSh 20,000 of the earlier credit customer balance arrives in the bank. Debit bank KSh 20,000; credit trade receivables KSh 20,000. 22 August: the business pays the advertising supplier KSh 5,000. Debit trade payables KSh 5,000; credit bank KSh 5,000. Neither payment is fresh income or a second expense."},{"title":"The final payment and a non-transaction","text":"25 August: the owner withdraws KSh 4,000 from the business bank for home use. Debit drawings KSh 4,000; credit bank KSh 4,000. That is the ninth recordable event. On 27 August, a potential customer requests a quotation for repairs priced at KSh 9,000. No work has been performed and no binding transaction is assumed; there is no journal entry for the enquiry. The accountant's job includes recognising when not to post."},{"title":"Post to the bank ledger, not just a journal list","text":"The bank ledger receives debit entries of KSh 180,000 from capital, KSh 45,000 from cash service fees and KSh 20,000 from the customer. Its credits are KSh 60,000 for equipment, KSh 12,000 for rent, KSh 5,000 to the supplier and KSh 4,000 for drawings. Debit total KSh 245,000; credit total KSh 81,000; closing debit bank balance KSh 164,000. Check that figure against the bank records."},{"title":"See what remains after posting","text":"Equipment has a KSh 60,000 debit balance; trade receivables KSh 15,000 debit; trade payables KSh 3,000 credit. Service revenue totals KSh 80,000 credit, while rent and advertising expenses carry debit balances of KSh 12,000 and KSh 8,000. Owner's capital is KSh 180,000 credit and drawings KSh 4,000 debit. Every one of these balances can be traced to the numbered events, not guessed."},{"title":"What the ledger gives the accountant","text":"The journal tells you what happened and how it was recorded. The ledger groups all movements by account, so you can answer questions like 'What is still owed to us?' and 'How much bank cash remains?' A posting error may preserve the equality of debits and credits while misclassifying the transaction. Supporting evidence and account reviews are therefore essential."}],"kenya_context_tab":[{"title":"An independent bookkeeper's assignment","text":"A Gilgil service business gives you a list of bank movements and invoices. First separate the bank receipt for work already invoiced from the invoice for work newly completed. Then post to receivables, bank and income so that the same customer payment never becomes income twice."},{"title":"Practice without software dependence","text":"The ledger logic works in a notebook, spreadsheet or production accounting package. A real accountant must recognise that an asset purchase on credit is debit equipment and credit the payable, even if the software generates both entries automatically."}],"common_errors_tab":[{"title":"Using debit to mean 'money out' everywhere","text":"A bank payment credits the bank, but the other account may be debited. Expenses increase with debits and income usually increases with credits. Decide which account increased or decreased first."},{"title":"Treating collection as a second sale","text":"Customer payment on an already recorded credit invoice reduces receivables and increases bank. If you credit revenue again, sales and profit will be overstated."},{"title":"Recording a quotation as a sale","text":"An enquiry or price quotation does not itself prove that a service was delivered or income earned. The correct response may be to retain the quotation without posting any ledger entry."}],"clinical_tip_tab":[{"title":"Ledger cross-check","text":"From the case above, calculate the bank account independently: KSh 180,000 minus 60,000 plus 45,000 minus 12,000 plus 20,000 minus 5,000 minus 4,000 equals KSh 164,000. Record the reason behind each plus or minus, not only the result."},{"title":"Accountant's habit","text":"When an amount fails to reconcile, return to the source, journal and ledger in that order. Correct the classification or posting. Do not create an unexplained suspense or balancing amount simply because the statement looks untidy."}]},{"slug":"trial-balance-from-ledgers","title":"Prove the ledger totals","subtitle":"Section 2.4 · Balance accounts and prepare a trial balance","sequence_number":7,"week_number":null,"concept_tab":[{"title":"What the trial balance actually checks","text":"The trial balance lists the debit and credit balances in the general ledger at a particular date. Total debits should equal total credits when every double-entry posting has been made consistently. It is a useful arithmetic checkpoint, not a certificate that every transaction was genuine or classified correctly. Start with ledger balances, not the amounts printed on every invoice."},{"title":"Bring forward the same business case","text":"At 31 August, Nuru Repair Studio has completed the nine recordable transactions from the previous lesson. The bank ledger shows KSh 164,000 debit. Equipment shows KSh 60,000 debit. Customers owe KSh 15,000; suppliers are owed KSh 3,000. Its service income totals KSh 80,000 credit, while rent, advertising and drawings have debit balances. There are no opening balances or further month-end adjustments in this exercise."},{"title":"Debit balances: work down the accounts","text":"Enter the debit balances in the trial balance: bank KSh 164,000; equipment KSh 60,000; trade receivables KSh 15,000; rent expense KSh 12,000; advertising expense KSh 8,000; drawings KSh 4,000. Add them in order: 164,000 + 60,000 = 224,000; +15,000 = 239,000; +12,000 = 251,000; +8,000 = 259,000; +4,000 = KSh 263,000."},{"title":"Credit balances: an independent total","text":"Enter the credit balances: owner's capital KSh 180,000; service revenue KSh 80,000; trade payables KSh 3,000. Add 180,000 + 80,000 + 3,000 = KSh 263,000. The debit total of KSh 263,000 agrees with the credit total. The agreement follows from the entries, not from inserting an amount to make the columns look equal."},{"title":"An account balance is not a total of transactions","text":"The bank ledger received KSh 245,000 of debits and KSh 81,000 of credits during the month. Its balance brought into the trial balance is KSh 164,000 debit, not KSh 245,000. Similarly, trade receivables started at KSh 35,000 but KSh 20,000 was collected, so the receivable balance is KSh 15,000. The trial balance contains the net account balances."},{"title":"When the totals disagree","text":"If debit balances sum to KSh 263,000 and credit balances to KSh 268,000, investigate the KSh 5,000 difference. Re-add each column, verify that the ledger balances were copied once to the correct side, inspect individual postings and confirm that both sides of each entry reached the appropriate accounts. Do not immediately enter KSh 5,000 in an invented expense account."},{"title":"Equal totals can still hide mistakes","text":"Suppose the business's KSh 5,000 payment to its advertising supplier is omitted from both the bank and payable ledgers. The trial balance can still agree: bank and payables are each KSh 5,000 too high. No arithmetic mismatch points to the omission. A second check against the bank record and supplier statement is required to find it."},{"title":"Know what comes next","text":"Once the ledger balances have been extracted and reviewed, the accountant uses income and expense accounts to calculate performance and asset, liability and equity balances to present the financial position. A trial balance is a bridge to statements, not the final report and not a replacement for any necessary adjustments."},{"title":"Check your own reconstruction","text":"Without looking back, calculate trade receivables after a KSh 35,000 credit invoice and KSh 20,000 customer payment. Then calculate trade payables after KSh 8,000 of advertising services on credit and KSh 5,000 paid. You should arrive at KSh 15,000 debit and KSh 3,000 credit. Explain why both balances matter to the owner."}],"kenya_context_tab":[{"title":"A month-end review in Kenya","text":"A self-employed accountant in Eldoret receives a bank statement, customer account list and supplier statements. The first trial balance agrees. Before reporting, the accountant checks whether all bank transactions and supplier settlements were actually posted. Equality of debit and credit totals cannot replace that independent source reconciliation."},{"title":"When software reports a green check","text":"An accounting platform may automatically keep debit and credit totals equal. That does not prove an invoice was posted to the right customer or an owner's withdrawal was coded as drawings. Source-to-ledger testing remains part of the accountant's responsibility."}],"common_errors_tab":[{"title":"Entering both sides of a ledger account","text":"The trial balance normally shows the closing net balance of an account, not all of its debit and credit movements. Recording both figures would distort the total and conceal what remains."},{"title":"Thinking equality proves accuracy","text":"A complete omission or an equally balanced incorrect journal can preserve equality. Use the trial balance to find certain errors, then use reconciliation and document checks to test completeness and classification."}],"clinical_tip_tab":[{"title":"Find the error before choosing a correction","text":"If a trial balance is out by KSh 5,000, begin with the KSh 5,000 difference, but do not assume the error is a single KSh 5,000 transaction. The cause may be one-sided posting, a transcription mistake or several errors whose effects combine."},{"title":"A useful supervisor's question","text":"When a report balances, ask what still has not been checked. If you can identify an evidence test outside the ledger, you are acting as an accountant rather than simply operating a calculator."}]},{"slug":"statements-from-the-trial-balance","title":"Turn balances into a business report","subtitle":"Section 2.5 · Profit or loss and financial position from the trial balance","sequence_number":8,"week_number":null,"concept_tab":[{"title":"Make the report answer a question","text":"The owner of Nuru Repair Studio wants two answers: Did the business earn a profit in August, and what does it own and owe at the end of the month? Those are different questions, so we prepare two different summaries from the same ledger balances. In a real set of financial statements, the reporting framework may also require cash-flow information, changes in equity and notes."},{"title":"Statement of profit or loss: start with income","text":"The August service revenue account has a credit balance of KSh 80,000, made up of KSh 35,000 earned on credit and KSh 45,000 received for completed cash services. Add both because income reflects services earned, not only cash received. There are no opening balances, returns or other income in this simplified exercise."},{"title":"Deduct the expenses that belong to August","text":"Rent used during the month was KSh 12,000. Advertising services delivered and used during the month cost KSh 8,000, even though KSh 3,000 remains payable. Total expenses are 12,000 + 8,000 = KSh 20,000. Profit for August is KSh 80,000 − KSh 20,000 = KSh 60,000. The advertising supplier payment of KSh 5,000 is not an additional expense."},{"title":"Statement of financial position: establish assets","text":"At 31 August the business has KSh 164,000 in the bank, equipment with a simplified carrying amount of KSh 60,000 and trade receivables of KSh 15,000. Total assets are 164,000 + 60,000 + 15,000 = KSh 239,000. The equipment value here ignores depreciation only because this introductory model deliberately excludes that later adjustment."},{"title":"Liabilities and the owner's remaining interest","text":"The advertising supplier is still owed KSh 3,000. The owner introduced KSh 180,000 of capital, the business earned KSh 60,000 and the owner withdrew KSh 4,000. Closing equity is 180,000 + 60,000 − 4,000 = KSh 236,000. Check the statement: assets KSh 239,000 = liabilities KSh 3,000 + equity KSh 236,000."},{"title":"Why profit, equity and bank balance differ","text":"Profit is KSh 60,000, the bank holds KSh 164,000 and equity is KSh 236,000. These figures are not competing versions of the same amount. The bank reflects receipts and payments, profit reflects recognised income and expenses, and equity includes owner capital, profit and drawings. The KSh 60,000 equipment purchase changed which asset the business owns, not its immediate operating profit."},{"title":"Do not add the customer payment to income twice","text":"Of KSh 35,000 of repairs invoiced on credit, KSh 20,000 is collected later. The full KSh 35,000 was included in August earned revenue when the work was completed under the stated assumptions. The subsequent collection moves KSh 20,000 from receivables to bank. Recognising another KSh 20,000 of revenue would inflate profit and make the statement misleading."},{"title":"A reporting cycle without pretending it is complete IFRS","text":"This lesson demonstrates how a basic trial balance feeds two introductory statements. A complete set of financial statements prepared under an applicable framework requires appropriate recognition, measurement, adjustments, presentation, comparative figures and disclosures. Subsequent CA11 units will address adjustments and more complex entities; do not call this short teaching example a complete IFRS-compliant annual report."},{"title":"Hand over a result someone can trust","text":"Before sending the report to the owner, confirm that the period is labelled, all balances come from the verified ledger, profit reconciles to the movement in equity, and assets equal liabilities plus equity. State any simplifying assumptions. An accountant earns trust by making the figures explainable and the limitations visible, not by suppressing an awkward question."}],"kenya_context_tab":[{"title":"Advice to a business owner","text":"A Meru workshop owner sees KSh 164,000 in the bank and wants to withdraw KSh 100,000. The accountant explains that a bank balance is not the whole story: there are supplier obligations, future operating needs and equipment-related costs. This lesson's statements are a starting point for that conversation, not a cash budget or a licence to withdraw."},{"title":"An accounting-system handover","text":"A computerised ledger may produce the trial balance and draft statements immediately after entries post. Your job is to compare the reports to the underlying events and check the classification. The software does not decide whether an owner's private withdrawal is a normal business expense."}],"common_errors_tab":[{"title":"Calling collections revenue twice","text":"Cash collected from a customer who already owes the business normally reduces the receivable. It is not another completed service, so the same transaction cannot be counted as a new sale."},{"title":"Profit is not the same as closing cash","text":"A business may make a profit while waiting for customers to pay; it may also have substantial bank funds from new owner capital or a loan. Use the performance and position reports together."},{"title":"Forgetting drawings in closing equity","text":"A personal withdrawal reduces the owner's interest but is not deducted from service profit as rent or advertising would be. It belongs in the movement from opening capital and earnings to closing equity."}],"clinical_tip_tab":[{"title":"The three-number cross-check","text":"For the August case, say these aloud and explain each: KSh 60,000 profit; KSh 236,000 closing equity; KSh 239,000 assets. If you cannot explain why the numbers differ, trace the capital contribution, credit sale, supplier balance and drawings again."},{"title":"Think beyond the statement","text":"A professional does not simply supply a profit figure. She should be able to tell the owner which customers still owe money, which supplier still needs payment and what assumptions were made when preparing the report."}]}],"questions":[{"topic_slug":"source-documents-and-evidence","question_text":"A workshop invoices a customer KSh 24,000 for work completed on credit. What is supported immediately by the invoice, under the stated recognition assumptions?","options":[{"id":"a","label":"A","text":"A new bank receipt of KSh 24,000."},{"id":"b","label":"B","text":"A trade receivable and service revenue of KSh 24,000."},{"id":"c","label":"C","text":"A reduction in the workshop's cash."},{"id":"d","label":"D","text":"A trade payable of KSh 24,000 owed by the workshop."}],"correct_option_id":"b","explanation":"The customer owes the workshop KSh 24,000 for completed work. The invoice supports a receivable and revenue, but does not show that payment has arrived."},{"topic_slug":"source-documents-and-evidence","question_text":"A client pays KSh 6,000 against a previously recorded KSh 16,000 credit invoice. With no other movements, how much does the client still owe?","options":[{"id":"a","label":"A","text":"KSh 22,000."},{"id":"b","label":"B","text":"KSh 6,000."},{"id":"c","label":"C","text":"KSh 10,000."},{"id":"d","label":"D","text":"Nothing; paying anything closes an invoice."}],"correct_option_id":"c","explanation":"The outstanding claim falls by the amount collected: KSh 16,000 less KSh 6,000 gives KSh 10,000. Do not recognise the collection as a second sale."},{"topic_slug":"source-documents-and-evidence","question_text":"Goods sold on credit for KSh 24,000 are partly returned, and the seller issues a valid KSh 3,000 credit note. No payments have been made. What remains receivable?","options":[{"id":"a","label":"A","text":"KSh 27,000."},{"id":"b","label":"B","text":"KSh 3,000."},{"id":"c","label":"C","text":"KSh 24,000."},{"id":"d","label":"D","text":"KSh 21,000."}],"correct_option_id":"d","explanation":"The accepted return reduces the customer's outstanding balance by KSh 3,000, leaving KSh 21,000. The credit note does not itself show cash was paid."},{"topic_slug":"source-documents-and-evidence","question_text":"Which document most directly supports the fact that a customer settled an earlier invoice by bank transfer?","options":[{"id":"a","label":"A","text":"A verified bank transaction record."},{"id":"b","label":"B","text":"The original credit invoice alone."},{"id":"c","label":"C","text":"A supplier's quotation."},{"id":"d","label":"D","text":"A list of next month's expected sales."}],"correct_option_id":"a","explanation":"The verified bank transaction supports receipt of funds. The invoice supports the underlying charge; the accountant should link the two, not confuse their purposes."},{"topic_slug":"source-documents-and-evidence","question_text":"A business pays the owner's private grocery bill from the business bank account. Which classification ordinarily fits a sole trader?","options":[{"id":"a","label":"A","text":"A business sales return."},{"id":"b","label":"B","text":"An increase in service revenue."},{"id":"c","label":"C","text":"Owner drawings supported by evidence of a personal payment."},{"id":"d","label":"D","text":"A trade receivable from a customer."}],"correct_option_id":"c","explanation":"The payment is a personal withdrawal, normally drawings for a sole trader. Paying it from the business bank does not make groceries an operating expense."},{"topic_slug":"source-documents-and-evidence","question_text":"When a customer disputes an invoice, which evidence trail gives the accountant the clearest way to investigate the recorded transaction?","options":[{"id":"a","label":"A","text":"A bank balance written in the diary."},{"id":"b","label":"B","text":"A manager's memory of yesterday."},{"id":"c","label":"C","text":"A list of payments with no references."},{"id":"d","label":"D","text":"A linked source document, transaction entry, ledger posting and subsequent settlement."}],"correct_option_id":"d","explanation":"Traceability joins the evidence to recording and settlement, enabling an independent reviewer to understand and correct the transaction without guessing."},{"topic_slug":"books-of-original-entry","question_text":"Under the traditional trading-business classification, which transaction belongs in a sales day book?","options":[{"id":"a","label":"A","text":"Cash sale of ordinary goods."},{"id":"b","label":"B","text":"Credit sale of goods held for resale."},{"id":"c","label":"C","text":"Sale of used equipment for cash."},{"id":"d","label":"D","text":"A customer deposit against an old invoice."}],"correct_option_id":"b","explanation":"The sales day book traditionally holds credit sales of trading goods. Cash sales and disposals of non-trading assets use other recording paths."},{"topic_slug":"books-of-original-entry","question_text":"A retailer acquires a delivery machine costing KSh 30,000 on supplier credit. What is the appropriate underlying general-journal entry?","options":[{"id":"a","label":"A","text":"Debit purchases; credit revenue."},{"id":"b","label":"B","text":"Debit bank; credit equipment."},{"id":"c","label":"C","text":"Debit equipment; credit trade payables."},{"id":"d","label":"D","text":"Debit rent; credit cash."}],"correct_option_id":"c","explanation":"A delivery machine used in operations is equipment rather than goods bought for resale. Debit equipment for the resource and credit the supplier payable."},{"topic_slug":"books-of-original-entry","question_text":"A business transfers KSh 4,500 from its bank to settle an electricity bill. Which first recording path is most suitable in a manual system?","options":[{"id":"a","label":"A","text":"Cash or bank payments book."},{"id":"b","label":"B","text":"Credit sales day book."},{"id":"c","label":"C","text":"Returns-inwards book."},{"id":"d","label":"D","text":"Credit purchases day book for trading goods."}],"correct_option_id":"a","explanation":"The cash book records bank payments and receipts. The expense account is also affected under double entry, but the bank movement should not be posted twice."},{"topic_slug":"books-of-original-entry","question_text":"Petty cash starts at KSh 5,000. Vouchers total KSh 1,250, KSh 700 and KSh 850. What replenishment restores the float?","options":[{"id":"a","label":"A","text":"KSh 5,000."},{"id":"b","label":"B","text":"KSh 2,200."},{"id":"c","label":"C","text":"KSh 3,500."},{"id":"d","label":"D","text":"KSh 2,800."}],"correct_option_id":"d","explanation":"Total petty expenses are KSh 2,800; cash remaining is KSh 2,200. Replacing KSh 2,800 restores the authorised KSh 5,000 float without a second expense."},{"topic_slug":"books-of-original-entry","question_text":"A shop issues a KSh 2,000 credit note for goods a customer returns from an earlier credit sale. Which specialised record is normally relevant?","options":[{"id":"a","label":"A","text":"Purchases day book."},{"id":"b","label":"B","text":"Returns-inwards day book."},{"id":"c","label":"C","text":"Cash sales record for a new sale."},{"id":"d","label":"D","text":"Capital contributions book."}],"correct_option_id":"b","explanation":"Goods returned by customers are sales returns, or returns inwards. The credit note provides support for reducing the earlier credit sale and receivable."},{"topic_slug":"books-of-original-entry","question_text":"An integrated accounting app posts ledger updates when an invoice is accepted. What remains the accountant's responsibility?","options":[{"id":"a","label":"A","text":"Record the same invoice once more in a manual journal."},{"id":"b","label":"B","text":"Assume every screen label proves the transaction is correct."},{"id":"c","label":"C","text":"Check evidence, classification, account effect and duplicates."},{"id":"d","label":"D","text":"Discard the invoice because the app has a sales total."}],"correct_option_id":"c","explanation":"Automatic postings make recording faster, not necessarily correct. The accountant must confirm that the evidence and account treatment match the actual event."},{"topic_slug":"double-entry-ledgers","question_text":"A sole trader introduces KSh 180,000 into the business bank account. Which entry is correct?","options":[{"id":"a","label":"A","text":"Debit capital; credit bank."},{"id":"b","label":"B","text":"Debit bank; credit capital."},{"id":"c","label":"C","text":"Debit bank; credit revenue."},{"id":"d","label":"D","text":"Debit drawings; credit bank."}],"correct_option_id":"b","explanation":"Bank increases as an asset, so debit bank. The owner's introduced capital increases equity, so credit capital for the same KSh 180,000."},{"topic_slug":"double-entry-ledgers","question_text":"The business buys equipment for KSh 60,000 by bank transfer. Which entry follows?","options":[{"id":"a","label":"A","text":"Debit equipment; credit bank."},{"id":"b","label":"B","text":"Debit bank; credit equipment."},{"id":"c","label":"C","text":"Debit rent expense; credit capital."},{"id":"d","label":"D","text":"Debit trade receivables; credit revenue."}],"correct_option_id":"a","explanation":"An equipment asset increases and bank cash falls. Debit equipment and credit bank, both KSh 60,000; no ordinary trading expense is assumed here."},{"topic_slug":"double-entry-ledgers","question_text":"Nuru Repair Studio completes KSh 35,000 of repairs on credit. Which accounts are affected at initial recognition?","options":[{"id":"a","label":"A","text":"Debit bank; credit payable."},{"id":"b","label":"B","text":"Debit expense; credit revenue."},{"id":"c","label":"C","text":"Debit revenue; credit receivable."},{"id":"d","label":"D","text":"Debit trade receivables; credit service revenue."}],"correct_option_id":"d","explanation":"Completed credit work creates a claim against the customer and earned income. Cash is not recorded until the customer settles the invoice."},{"topic_slug":"double-entry-ledgers","question_text":"The bank starts with KSh 180,000, then movements are −60,000, +45,000, −12,000, +20,000, −5,000 and −4,000. What is the closing bank balance?","options":[{"id":"a","label":"A","text":"KSh 156,000."},{"id":"b","label":"B","text":"KSh 184,000."},{"id":"c","label":"C","text":"KSh 164,000."},{"id":"d","label":"D","text":"KSh 245,000."}],"correct_option_id":"c","explanation":"Add receipts of KSh 245,000 and deduct payments totalling KSh 81,000. The closing debit bank balance is KSh 164,000, not gross receipts."},{"topic_slug":"double-entry-ledgers","question_text":"Advertising services worth KSh 8,000 are used on credit, then KSh 5,000 is paid to the supplier. What remains payable?","options":[{"id":"a","label":"A","text":"KSh 13,000."},{"id":"b","label":"B","text":"KSh 3,000."},{"id":"c","label":"C","text":"KSh 8,000."},{"id":"d","label":"D","text":"Zero because some cash was paid."}],"correct_option_id":"b","explanation":"The liability begins at KSh 8,000 when the service is received. Paying KSh 5,000 reduces the payable to KSh 3,000; it does not create a second expense."},{"topic_slug":"double-entry-ledgers","question_text":"A potential customer asks for a price quotation for future repairs; no work has been done and no binding transaction is assumed. Which posting is justified?","options":[{"id":"a","label":"A","text":"Debit receivables; credit revenue."},{"id":"b","label":"B","text":"Debit cash; credit revenue."},{"id":"c","label":"C","text":"Debit advertising; credit payable."},{"id":"d","label":"D","text":"No accounting entry yet, but retain the quotation for reference."}],"correct_option_id":"d","explanation":"The enquiry does not establish that income was earned or an asset created. Retaining the quote is sound administration, not a double-entry transaction."},{"topic_slug":"trial-balance-from-ledgers","question_text":"The trial balance lists debit balances of KSh 164,000 bank, 60,000 equipment, 15,000 receivables, 12,000 rent, 8,000 advertising and 4,000 drawings. What is the debit total?","options":[{"id":"a","label":"A","text":"KSh 263,000."},{"id":"b","label":"B","text":"KSh 259,000."},{"id":"c","label":"C","text":"KSh 243,000."},{"id":"d","label":"D","text":"KSh 239,000."}],"correct_option_id":"a","explanation":"Adding all six debit balances gives KSh 263,000. Drawings is a debit balance and must be included when extracting the trial balance."},{"topic_slug":"trial-balance-from-ledgers","question_text":"The same trial balance lists credit balances of KSh 180,000 capital, KSh 80,000 revenue and KSh 3,000 payables. What is the credit total?","options":[{"id":"a","label":"A","text":"KSh 260,000."},{"id":"b","label":"B","text":"KSh 243,000."},{"id":"c","label":"C","text":"KSh 263,000."},{"id":"d","label":"D","text":"KSh 283,000."}],"correct_option_id":"c","explanation":"Credits total KSh 180,000 plus KSh 80,000 plus KSh 3,000, or KSh 263,000, matching the independent debit total."},{"topic_slug":"trial-balance-from-ledgers","question_text":"The bank ledger has KSh 245,000 of debit movements and KSh 81,000 of credit movements. Which figure enters a basic trial balance?","options":[{"id":"a","label":"A","text":"KSh 245,000 on the debit side."},{"id":"b","label":"B","text":"KSh 81,000 on the credit side."},{"id":"c","label":"C","text":"Both totals as separate balances."},{"id":"d","label":"D","text":"KSh 164,000 on the debit side."}],"correct_option_id":"d","explanation":"The trial balance uses the net closing balance of the bank account: KSh 245,000 less KSh 81,000 equals KSh 164,000 debit."},{"topic_slug":"trial-balance-from-ledgers","question_text":"A KSh 5,000 payment to a creditor is accidentally omitted from both the bank and payable ledgers. What may happen to the trial balance?","options":[{"id":"a","label":"A","text":"It must become KSh 10,000 out of balance."},{"id":"b","label":"B","text":"It may still balance even though both balances are overstated."},{"id":"c","label":"C","text":"Profit must increase by KSh 5,000."},{"id":"d","label":"D","text":"Bank must show a KSh 5,000 credit balance."}],"correct_option_id":"b","explanation":"Both sides of the omitted transaction are missing, so debit and credit totals may remain equal while bank and creditor balances are both overstated."},{"topic_slug":"trial-balance-from-ledgers","question_text":"The debit trial-balance column totals KSh 263,000 and the credit column KSh 268,000. What should the accountant do?","options":[{"id":"a","label":"A","text":"Investigate the KSh 5,000 difference by rechecking balances and postings."},{"id":"b","label":"B","text":"Create an unexplained expense of KSh 5,000 immediately."},{"id":"c","label":"C","text":"Assume profit is KSh 5,000 lower."},{"id":"d","label":"D","text":"Delete a credit balance to make the columns agree."}],"correct_option_id":"a","explanation":"The KSh 5,000 difference is a clue, not authority to invent an entry. Re-add and trace balances and investigate the source before correcting records."},{"topic_slug":"trial-balance-from-ledgers","question_text":"Credit repairs of KSh 35,000 are followed by a customer payment of KSh 20,000. What receivable balance enters the trial balance?","options":[{"id":"a","label":"A","text":"KSh 55,000 credit."},{"id":"b","label":"B","text":"KSh 35,000 debit."},{"id":"c","label":"C","text":"KSh 15,000 debit."},{"id":"d","label":"D","text":"KSh 20,000 credit."}],"correct_option_id":"c","explanation":"The customer owes the difference, KSh 15,000. The bank receipt reduces the receivable rather than creating new revenue."},{"topic_slug":"statements-from-the-trial-balance","question_text":"Nuru Repair Studio earns KSh 80,000 revenue and incurs KSh 12,000 rent plus KSh 8,000 advertising expense. What is the period's profit?","options":[{"id":"a","label":"A","text":"KSh 80,000."},{"id":"b","label":"B","text":"KSh 60,000."},{"id":"c","label":"C","text":"KSh 72,000."},{"id":"d","label":"D","text":"KSh 20,000."}],"correct_option_id":"b","explanation":"Revenue of KSh 80,000 less total expenses of KSh 20,000 leaves KSh 60,000 profit. The KSh 5,000 supplier payment is not a separate expense."},{"topic_slug":"statements-from-the-trial-balance","question_text":"Closing assets are bank KSh 164,000, equipment KSh 60,000 and receivables KSh 15,000. What is total assets?","options":[{"id":"a","label":"A","text":"KSh 239,000."},{"id":"b","label":"B","text":"KSh 224,000."},{"id":"c","label":"C","text":"KSh 179,000."},{"id":"d","label":"D","text":"KSh 236,000."}],"correct_option_id":"a","explanation":"Add the three recognised assets: KSh 164,000 + 60,000 + 15,000 = KSh 239,000, under this teaching model's stated assumptions."},{"topic_slug":"statements-from-the-trial-balance","question_text":"The owner introduced KSh 180,000, the business earned KSh 60,000 and the owner withdrew KSh 4,000. What is closing equity?","options":[{"id":"a","label":"A","text":"KSh 244,000."},{"id":"b","label":"B","text":"KSh 180,000."},{"id":"c","label":"C","text":"KSh 240,000."},{"id":"d","label":"D","text":"KSh 236,000."}],"correct_option_id":"d","explanation":"Capital plus retained current-period profit minus drawings gives KSh 180,000 + 60,000 − 4,000 = KSh 236,000 closing equity."},{"topic_slug":"statements-from-the-trial-balance","question_text":"With assets of KSh 239,000 and equity of KSh 236,000, what is the outstanding liability?","options":[{"id":"a","label":"A","text":"KSh 6,000."},{"id":"b","label":"B","text":"KSh 60,000."},{"id":"c","label":"C","text":"KSh 3,000."},{"id":"d","label":"D","text":"KSh 23,000."}],"correct_option_id":"c","explanation":"Liabilities are assets less equity: KSh 239,000 − KSh 236,000 = KSh 3,000, agreeing with the unpaid advertising supplier balance."},{"topic_slug":"statements-from-the-trial-balance","question_text":"Why is KSh 164,000 bank cash not equal to the KSh 60,000 accounting profit?","options":[{"id":"a","label":"A","text":"Because a trial balance cannot contain bank cash."},{"id":"b","label":"B","text":"Because cash includes capital and settlements while profit measures earned income less expenses."},{"id":"c","label":"C","text":"Because every cash withdrawal reduces profit automatically."},{"id":"d","label":"D","text":"Because the difference must be an accounting error."}],"correct_option_id":"b","explanation":"Bank receipts and payments include financing and asset purchases as well as earnings. Profit follows recognised income and expenses, so the two figures answer different questions."},{"topic_slug":"statements-from-the-trial-balance","question_text":"What is the correct professional description of the teaching statements prepared from this simplified trial balance?","options":[{"id":"a","label":"A","text":"Basic introductory profit-or-loss and position statements requiring further adjustments/disclosures for a complete applicable-framework report."},{"id":"b","label":"B","text":"A complete IFRS annual report without notes or comparative figures."},{"id":"c","label":"C","text":"A statutory audit opinion on Nuru Repair Studio."},{"id":"d","label":"D","text":"The same information as a cash-flow statement because all totals agree."}],"correct_option_id":"a","explanation":"The figures demonstrate the reporting link but omit depreciation, tax, other adjustments and full presentation or disclosure requirements. They are not a complete annual IFRS report."}]}$unit02data$::jsonb);

do $unit02_preflight$
declare v_course public.courses%rowtype; v_module public.modules%rowtype; v_intro_count integer;
begin
  select * into v_course from public.courses
  where slug='kasneb-cpa' and status='live'
    and qualification_code='CPA' and qualifying_body='KASNEB'
    and syllabus_source_url like 'https://www.kasneb.or.ke/%';
  if not found then raise exception 'CA11 Unit 02 source-qualified live CPA course not found'; end if;
  select * into v_module from public.modules
  where course_id=v_course.id and slug='ca11' and qualification_level='Foundation'
    and qualification_requirement='required';
  if not found then raise exception 'CA11 Unit 02 cannot resolve canonical Foundation paper'; end if;
  select count(*) into v_intro_count from public.topics
  where module_id=v_module.id and content_status='published'
    and slug in ('why-accounts-matter','five-elements-of-financial-statements','the-equation-in-action');
  if v_intro_count<>3 then raise exception 'CA11 Unit 01 must remain fully published'; end if;
  if (select count(*) from public.topics where module_id=v_module.id) <> 3 then
    raise exception 'CA11 Unit 02 collision or unreviewed concurrent content detected';
  end if;
  if (select count(*) from public.topics t join public.modules m on m.id=t.module_id
      where m.course_id=v_course.id and m.slug<>'ca11')<>0 then
    raise exception 'CA11 Unit 02 cannot stage beside unverified other CPA paper content';
  end if;
  if (select data->'manifest'->>'release_state' from pg_temp.vibeschool_ca11_unit02_packet)<>'in_review' then
    raise exception 'CA11 Unit 02 authoring packet is not review-only';
  end if;
end $unit02_preflight$;

with packet as (select data from pg_temp.vibeschool_ca11_unit02_packet),
target as (
 select m.id module_id from public.modules m
 join public.courses c on c.id=m.course_id
 where c.slug='kasneb-cpa' and m.slug='ca11'
),
authored as (
 select t.*,target.module_id
 from packet cross join target cross join lateral jsonb_to_recordset(packet.data->'topics') as t(
  slug text,title text,subtitle text,sequence_number integer,week_number integer,
  concept_tab jsonb,kenya_context_tab jsonb,common_errors_tab jsonb,clinical_tip_tab jsonb
 )
)
insert into public.topics(
 module_id,slug,title,subtitle,sequence_number,week_number,
 concept_tab,kenya_context_tab,common_errors_tab,clinical_tip_tab,content_status
)
select module_id,slug,title,subtitle,sequence_number,null,
 concept_tab,kenya_context_tab,common_errors_tab,clinical_tip_tab,'in_review'
from authored;

with packet as (select data from pg_temp.vibeschool_ca11_unit02_packet),
authored as (
 select x.*, t.id topic_id
 from packet cross join lateral jsonb_to_recordset(packet.data->'questions') as x(
   topic_slug text,question_text text,options jsonb,correct_option_id text,explanation text
 )
 join public.topics t on t.slug=x.topic_slug
 join public.modules m on m.id=t.module_id
 join public.courses c on c.id=m.course_id
 where c.slug='kasneb-cpa' and m.slug='ca11'
)
insert into public.quiz_questions(topic_id,question_text,options,correct_option_id,explanation)
select topic_id,question_text,options,correct_option_id,explanation
from authored;

do $unit02_verify$
declare
 v_topics int;v_questions int;v_invalid int;v_intro int;v_other int;
begin
 select count(*) into v_topics from public.topics t
 join public.modules m on m.id=t.module_id
 join public.courses c on c.id=m.course_id
 where c.slug='kasneb-cpa' and m.slug='ca11' and t.slug in ('source-documents-and-evidence','books-of-original-entry','double-entry-ledgers','trial-balance-from-ledgers','statements-from-the-trial-balance')
 and t.content_status='in_review' and t.sequence_number between 4 and 8
 and t.week_number is null
 and jsonb_array_length(t.concept_tab)>=7
 and jsonb_array_length(t.kenya_context_tab)>=2
 and jsonb_array_length(t.common_errors_tab)>=2;
 if v_topics<>5 then raise exception 'Expected 5 reviewed CA11 Unit 02 topics; got %',v_topics; end if;
 select count(*) into v_questions from public.quiz_questions q
 join public.topics t on t.id=q.topic_id
 join public.modules m on m.id=t.module_id join public.courses c on c.id=m.course_id
 where c.slug='kasneb-cpa' and m.slug='ca11' and t.slug in ('source-documents-and-evidence','books-of-original-entry','double-entry-ledgers','trial-balance-from-ledgers','statements-from-the-trial-balance');
 if v_questions<>30 then raise exception 'Expected 30 CA11 Unit 02 practice questions; got %',v_questions; end if;
 select count(*) into v_invalid from public.quiz_questions q
 join public.topics t on t.id=q.topic_id
 join public.modules m on m.id=t.module_id
 join public.courses c on c.id=m.course_id
 where c.slug='kasneb-cpa' and m.slug='ca11' and t.slug in ('source-documents-and-evidence','books-of-original-entry','double-entry-ledgers','trial-balance-from-ledgers','statements-from-the-trial-balance') and (
  jsonb_typeof(q.options) is distinct from 'array'
  or jsonb_array_length(q.options)<>4
  or not exists(select 1 from jsonb_array_elements(q.options) opt where opt->>'id'=q.correct_option_id)
  or length(btrim(coalesce(q.explanation,'')))<75
 );
 if v_invalid<>0 then raise exception 'CA11 answer authority/explanations invalid: %',v_invalid; end if;
 select count(*) into v_intro from public.topics t join public.modules m on m.id=t.module_id
 join public.courses c on c.id=m.course_id
 where c.slug='kasneb-cpa' and m.slug='ca11' and t.content_status='published';
 if v_intro<>3 then raise exception 'Previously published CA11 Unit 01 topics modified'; end if;
 select count(*) into v_other from public.topics t join public.modules m on m.id=t.module_id
 join public.courses c on c.id=m.course_id
 where c.slug='kasneb-cpa' and m.slug<>'ca11';
 if v_other<>0 then raise exception 'Unrelated CPA content was modified'; end if;
end $unit02_verify$;
commit;
